def unletterbox_box(box, orig_w, orig_h, size=640):
    r = min(size / orig_w, size / orig_h)
    new_w, new_h = round(orig_w * r), round(orig_h * r)
    pad_x = (size - new_w) / 2
    pad_y = (size - new_h) / 2
    x1, y1, x2, y2 = box
    x1 = (x1 - pad_x) / r
    y1 = (y1 - pad_y) / r
    x2 = (x2 - pad_x) / r
    y2 = (y2 - pad_y) / r

    def clip(v, hi):
        return min(max(v, 0.0), hi)

    return (clip(x1, orig_w), clip(y1, orig_h), clip(x2, orig_w), clip(y2, orig_h))
